  var game=new GameFlow{Player=new WolfMotor(),Health=100,Panel=""};game.Player.game=game;game.Services.game=game;var heaven=new HeavenlyGarden{game=game};game.Heaven=heaven;var garden=new GameObject();var palace=new GameObject();palace.transform.SetParent(garden.transform,false);Put(heaven,"garden",garden);Put(heaven,"palace",palace);
