  game.Player.transform.position=HeavenlyGarden.Centre;HeavenPhysicsFixture.hits=new[]{new RaycastHit{collider=new Collider{name="Heaven garden ground · original mesh"},point=HeavenlyGarden.Centre}};Check(HeavenlyGarden.Water(game.Player.transform.position,out var water,out var depth) && depth<.2f,"Shallow pond still deep");game.Player.input.Interact.pressedThisFrame=true;Check(Call(heaven,"GardenInteractions") && game.Services.restRequests==1,"E inside shallow pond does not sit");Check(Math.Abs(game.Services.restPoint.y-70.025f)<.001,"Pond sitting floats or sinks player");
  game.Player.input.Interact.pressedThisFrame=false;HeavenPhysicsFixture.hits=Array.Empty<RaycastHit>();typeof(HeavenlyGarden).GetField("activeGarden",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,null);
  var body=new NativeAmaterasu();typeof(NativeAmaterasu).GetMethod("Awake",flags).Invoke(body,null);Check(body.Ready,"Native player cannot load current bindings");body.Play("NativeCharge_glaive",.1f,0,true,false);body.HoldChargePose();var nativeClip=(NativePoseBank.Clip)typeof(NativeAmaterasu).GetField("clip",flags).GetValue(body);Check(nativeClip.Name=="pl00_523" && body.PlaybackRate>0,"Held glaive uses a rosary clip or stopped clock");Time.deltaTime=.016f;float phase=body.Phase;typeof(NativeAmaterasu).GetMethod("LateUpdate",flags).Invoke(body,null);Check(body.Phase>phase,"Glaive preparation freezes while held");body.Play("NativeAttack_524",.1f,.6666667f,true,false);for(int i=0;i<70;i++)typeof(NativeAmaterasu).GetMethod("LateUpdate",flags).Invoke(body,null);var rig=(NativePaintedRig)typeof(NativeAmaterasu).GetField("rig",flags).GetValue(body);var motions=(NativePoseBank)typeof(NativeAmaterasu).GetField("bank",flags).GetValue(body);Check(Vector3.Distance(rig.Bones[1].localPosition,motions.Find("pl00_000").Position[1])<.001f,"Glaive release holds displaced final pose instead of recovering");
  Console.WriteLine("PASS "+count+" palace entry/exit, realm isolation, elemental colour and shallow pond sitting checks; engine doubles, not Unity");
